insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-1502', '["phrase"]'::jsonb, '{"advanced-native-1502-v1-audio":{"type":"mc","answers":["保留目的，改用配合現在情況的參與方式。"],"options":["習俗只保留原來參與方式，不接受網上加入。","家人已放棄習俗的目的，改辦不相關活動。","句子只說參與人數增加，沒有說做法調整。","保留目的，改用配合現在情況的參與方式。"]},"advanced-native-1502-v2-reply":{"type":"mc","answers":["The purpose is to share time together, even from different places.","A flexible format can help more people take part.","The custom can breathe with the times while keeping people connected.","Some relatives now live too far away to attend in person."],"options":["The purpose is to share time together, even from different places.","A flexible format can help more people take part.","The custom can breathe with the times while keeping people connected.","Some relatives now live too far away to attend in person."]},"advanced-native-1502-v1-scene":{"type":"mc","answers":["The custom can breathe with the times."],"options":["The custom remains unchanged in both purpose and format.","The family has replaced its shared stories with an unrelated event.","The custom can breathe with the times."]},"advanced-native-1502-v1-contrast":{"type":"mc","answers":["只因一種做法很新，就在未考慮目的前採用。"],"options":["只因一種做法很新，就在未考慮目的前採用。","檢視現在需要，保留意義並改良安排。","調整參與方式，讓習俗繼續有用。"]},"advanced-native-1502-v1-branch":{"type":"mc","answers":["A custom can breathe with the times through useful changes while keeping its main purpose."],"options":["A custom can breathe with the times through useful changes while keeping its main purpose.","Replace the shared purpose first and decide later whether the new format serves the family.","Keep the format unchanged until distant relatives can attend in person again."]},"advanced-native-1502-v1-final":{"type":"open","answers":["The ceremony can breathe with the times by allowing smart casual clothes while keeping the awards.","We want the ceremony to breathe with the times. A flexible dress rule could help students take part without losing the celebration of effort."],"options":[]}}'::jsonb),
('advanced-native-1503', '["phrase"]'::jsonb, '{"advanced-native-1503-v1-audio":{"type":"mc","answers":["散步成為平常生活的一部分。"],"options":["散步成為平常生活的一部分。","家人只在一年一度活動時散步。","家人打算開始散步，但尚未付諸實行。","句子重點是一次散步比原定路程長。"]},"advanced-native-1503-v2-reply":{"type":"mc","answers":["The stories come up naturally in ordinary conversations.","Storytelling is woven into daily routines at home.","They often hear the stories while helping with dinner.","Relatives connect the stories with things that happen each day."],"options":["The stories come up naturally in ordinary conversations.","Storytelling is woven into daily routines at home.","They often hear the stories while helping with dinner.","Relatives connect the stories with things that happen each day."]},"advanced-native-1503-v1-scene":{"type":"mc","answers":["Sharing stories is woven into daily routines."],"options":["Sharing stories is woven into daily routines.","Sharing stories is reserved for the annual reunion.","Sharing stories is an idea the family has not tried yet."]},"advanced-native-1503-v1-contrast":{"type":"mc","answers":["只在一次特別展覽當天試做活動，之後沒有再做。"],"options":["每晚收拾後花幾分鐘讀書。","只在一次特別展覽當天試做活動，之後沒有再做。","平日早餐時自然聊當天安排。"]},"advanced-native-1503-v1-branch":{"type":"mc","answers":["To be woven into daily routines, it needs a place in ordinary repeated activities."],"options":["Describe the activity as a daily habit now and plan its next use later.","To be woven into daily routines, it needs a place in ordinary repeated activities.","Use the size of the one-day event to decide how regular the activity has become."]},"advanced-native-1503-v1-final":{"type":"open","answers":["Caring for the school garden is woven into daily routines. Students water the plants and record changes at lunchtime.","Garden care is now woven into daily routines rather than saved for open days. Each group has a regular lunchtime task."],"options":[]}}'::jsonb),
('advanced-native-1504', '["phrase"]'::jsonb, '{"advanced-native-1504-v1-audio":{"type":"mc","answers":["餐牌很多元，但仍有連貫的廣東飲食影響。"],"options":["句子只說餐牌用廣東話印製，沒有談味道。","餐牌很多元，但仍有連貫的廣東飲食影響。","餐牌已移除廣東湯底與調味。","餐牌只有廣東菜，沒有其他地方的菜式。"]},"advanced-native-1504-v2-reply":{"type":"mc","answers":["The Cantonese thread still runs through it in the broths and seasonings.","Several dishes use flavours they know from home.","The chef has kept some familiar cooking methods.","The local touches connect the dishes despite their varied origins."],"options":["The Cantonese thread still runs through it in the broths and seasonings.","Several dishes use flavours they know from home.","The chef has kept some familiar cooking methods.","The local touches connect the dishes despite their varied origins."]},"advanced-native-1504-v1-scene":{"type":"mc","answers":["The Cantonese thread still runs through it."],"options":["The menu has abandoned its Cantonese cooking influences.","The menu contains Cantonese dishes to the exclusion of other cuisines.","The Cantonese thread still runs through it."]},"advanced-native-1504-v1-contrast":{"type":"mc","answers":["有廣東話菜名，但烹調、味道和設計未見廣東元素。"],"options":["有廣東話菜名，但烹調、味道和設計未見廣東元素。","多元菜式中可辨認共同的廣東調味方法。","多道菜仍採用熟悉廣東湯底。"]},"advanced-native-1504-v1-branch":{"type":"mc","answers":["An international menu can change while the Cantonese thread still runs through it."],"options":["Count the Cantonese names without checking whether the flavours carry the same influence.","An international menu can change while the Cantonese thread still runs through it.","Classify the menu only by its newest foreign dish before examining the shared cooking methods."]},"advanced-native-1504-v1-final":{"type":"open","answers":["The collection includes food stories from many places, but the Cantonese thread still runs through it in memories of family cooking.","The authors explore different cuisines in this collection, yet the Cantonese thread still runs through it, linking the stories through familiar family recipes."],"options":[]}}'::jsonb),
('advanced-native-1505', '["phrase"]'::jsonb, '{"advanced-native-1505-v1-audio":{"type":"mc","answers":["米飯在平日飲食安排中有核心地位。"],"options":["句子說村民完全不吃其他食物。","米飯只是剛試過、尚未成習慣的新菜式。","米飯在平日飲食安排中有核心地位。","村民只在年度宴會才吃米飯。"]},"advanced-native-1505-v2-reply":{"type":"mc","answers":["Most everyday meals are organised around it.","It provides a useful starting point for explaining common meals.","Many of the side dishes are usually served with it.","Rice is the backbone of local eating habits here."],"options":["Most everyday meals are organised around it.","It provides a useful starting point for explaining common meals.","Many of the side dishes are usually served with it.","Rice is the backbone of local eating habits here."]},"advanced-native-1505-v1-scene":{"type":"mc","answers":["That staple is the backbone of local eating habits."],"options":["That staple is mainly an occasional festival treat.","That staple has only just appeared and has no established place in meals.","That staple is the backbone of local eating habits."]},"advanced-native-1505-v1-contrast":{"type":"mc","answers":["一場試食會有人喜歡一道新甜品，但未見日常食用情況。"],"options":["長期觀察顯示平常飯餐多以該主食為中心。","一場試食會有人喜歡一道新甜品，但未見日常食用情況。","家庭訪問反覆提到該主食是安排飯餐的基礎。"]},"advanced-native-1505-v1-branch":{"type":"mc","answers":["To call it the backbone of local eating habits, check its role in ordinary meals over time."],"options":["Use the queue at one tasting event as the main evidence of its everyday role.","Rank the dishes by their prices before checking how often households eat them.","To call it the backbone of local eating habits, check its role in ordinary meals over time."]},"advanced-native-1505-v1-final":{"type":"open","answers":["Noodles, rather than the festival sweet, are the backbone of local eating habits in this fictional town. The museum text should reflect everyday meals.","Our interviews suggest that noodles are the backbone of local eating habits. We should not confuse a yearly treat with an everyday staple."],"options":[]}}'::jsonb),
('advanced-native-1506', '["phrase"]'::jsonb, '{"advanced-native-1506-v1-audio":{"type":"mc","answers":["多種飲食傳統在社區接觸交流。"],"options":["社區只保留一種飲食傳統，排除其他影響。","廚師來自不同地方，但彼此從不接觸。","分享之後，廚師已不再保留各自傳統特色。","多種飲食傳統在社區接觸交流。"]},"advanced-native-1506-v2-reply":{"type":"mc","answers":["Local cooks exchange ideas with people from different backgrounds.","The menu reflects the mix of communities living nearby.","The neighbourhood is a real melting pot.","Families bring recipes from several traditions."],"options":["Local cooks exchange ideas with people from different backgrounds.","The menu reflects the mix of communities living nearby.","The neighbourhood is a real melting pot.","Families bring recipes from several traditions."]},"advanced-native-1506-v1-scene":{"type":"mc","answers":["The market is a real melting pot."],"options":["The stalls follow separate traditions without exchanging ideas.","The market is a real melting pot.","The market specialises in one tradition and keeps other influences out."]},"advanced-native-1506-v1-contrast":{"type":"mc","answers":["融合必然要求每種文化的特色完全消失。"],"options":["一個地方可同時有交流與可辨認的不同傳統。","不同背景的影響相遇，形成多元組合。","融合必然要求每種文化的特色完全消失。"]},"advanced-native-1506-v1-branch":{"type":"mc","answers":["A real melting pot can combine influences while still keeping recognisable differences."],"options":["A real melting pot can combine influences while still keeping recognisable differences.","Judge the mix mainly by whether every stall serves the same flavour.","Keep the cooks apart so their traditions will count as a shared mix."]},"advanced-native-1506-v1-final":{"type":"open","answers":["Our arts day is a real melting pot of musical traditions. Students share rhythms and create performances together.","The arts day feels like a real melting pot, bringing different backgrounds together while keeping distinctive musical styles."],"options":[]}}'::jsonb),
('advanced-native-1507', '["phrase"]'::jsonb, '{"advanced-native-1507-v1-audio":{"type":"mc","answers":["他們在附近品嘗不同文化傳統的菜式。"],"options":["他們在附近品嘗不同文化傳統的菜式。","他們只在出國時才接觸不同菜式。","他們每次都選相同傳統的同一道菜。","句子主要說他們已全面掌握每種文化的歷史。"]},"advanced-native-1507-v2-reply":{"type":"mc","answers":["I like comparing how cooks use similar ingredients in different ways.","I enjoy eating across cultures and discovering unfamiliar dishes.","Different recipes give me new flavours to explore.","My friends introduce me to dishes their families enjoy."],"options":["I like comparing how cooks use similar ingredients in different ways.","I enjoy eating across cultures and discovering unfamiliar dishes.","Different recipes give me new flavours to explore.","My friends introduce me to dishes their families enjoy."]},"advanced-native-1507-v1-scene":{"type":"mc","answers":["They enjoy eating across cultures."],"options":["They have to travel abroad before they can try those dishes.","Their meals stay within a single cooking tradition.","They enjoy eating across cultures."]},"advanced-native-1507-v1-contrast":{"type":"mc","answers":["到不同地方，但每餐仍只吃自己熟悉的同一種菜式。"],"options":["到不同地方，但每餐仍只吃自己熟悉的同一種菜式。","與朋友分享各自家庭傳統的食物。","在同一城市品嘗不同文化菜式。"]},"advanced-native-1507-v1-branch":{"type":"mc","answers":["Eating across cultures can happen locally when we try dishes from different traditions."],"options":["Choose the same familiar meal throughout the trip and use travel itself as evidence of varied eating.","Eating across cultures can happen locally when we try dishes from different traditions.","Count the countries visited rather than looking at which dishes were tried."]},"advanced-native-1507-v1-final":{"type":"open","answers":["We want to try eating across cultures at home by cooking dishes from different traditions each week.","Eating across cultures can become a shared cooking project for our family. Friends can explain the dishes before we try the recipes."],"options":[]}}'::jsonb),
('advanced-native-1508', '["phrase"]'::jsonb, '{"advanced-native-1508-v1-audio":{"type":"mc","answers":["Maya 答應時沒有表露驚訝或介意。"],"options":["句子證明 Maya 心裏完全沒有任何緊張。","Maya 答應時沒有表露驚訝或介意。","Maya 明顯驚慌，要求很久後才再回答。","Maya 拒絕了發言邀請，沒有答應。"]},"advanced-native-1508-v2-reply":{"type":"mc","answers":["She agreed without batting an eyelid.","She stayed calm and said she could do it.","She showed no obvious sign of surprise.","Her reply was steady despite the unexpected request."],"options":["She agreed without batting an eyelid.","She stayed calm and said she could do it.","She showed no obvious sign of surprise.","Her reply was steady despite the unexpected request."]},"advanced-native-1508-v1-scene":{"type":"mc","answers":["She accepted without batting an eyelid."],"options":["She showed clear alarm before accepting.","She declined because the request surprised her.","She accepted without batting an eyelid."]},"advanced-native-1508-v1-contrast":{"type":"mc","answers":["當事人內心一定完全沒有緊張。"],"options":["當事人沒有表露驚訝。","當事人內心一定完全沒有緊張。","當事人面對意外要求仍顯得鎮定。"]},"advanced-native-1508-v1-branch":{"type":"mc","answers":["Without batting an eyelid describes the reaction, not how difficult the task really is."],"options":["Use her calm expression as the main evidence that she needs no preparation.","Assume that accepting quickly means she had expected the request.","Without batting an eyelid describes the reaction, not how difficult the task really is."]},"advanced-native-1508-v1-final":{"type":"open","answers":["He accepted the surprisingly high repair quote without batting an eyelid, then read the written details carefully.","The character agreed without batting an eyelid when he heard the price. His calm reaction does not tell us everything he felt."],"options":[]}}'::jsonb),
('advanced-native-1509', '["phrase"]'::jsonb, '{"advanced-native-1509-v1-audio":{"type":"mc","answers":["她的閱讀範圍已比以前廣。"],"options":["她已完全放棄犯罪小說，不再接觸。","她只改變閱讀時間，類型沒有增加。","她的閱讀範圍已比以前廣。","她現在仍只讀犯罪小說。"]},"advanced-native-1509-v2-reply":{"type":"mc","answers":["Members wanted to discover books outside their usual choices.","Different genres give us new kinds of questions to discuss.","We can keep favourites while exploring unfamiliar writing.","I did not want our reading to stay stuck in one lane."],"options":["Members wanted to discover books outside their usual choices.","Different genres give us new kinds of questions to discuss.","We can keep favourites while exploring unfamiliar writing.","I did not want our reading to stay stuck in one lane."]},"advanced-native-1509-v1-scene":{"type":"mc","answers":["Its reading is no longer stuck in one lane."],"options":["Its reading remains limited to detective novels.","It has replaced detective novels rather than broadened the selection.","Its reading is no longer stuck in one lane."]},"advanced-native-1509-v1-contrast":{"type":"mc","answers":["團隊本週專心完成一項任務，但平常會比較多種方法。"],"options":["閱讀選擇一直局限同一類，想拓展卻沒有嘗試。","長期只接受一種方法，未考慮其他可行選擇。","團隊本週專心完成一項任務，但平常會比較多種方法。"]},"advanced-native-1509-v1-branch":{"type":"mc","answers":["We can avoid being stuck in one lane by adding new genres while keeping some favourites."],"options":["We can avoid being stuck in one lane by adding new genres while keeping some favourites.","Replace one favourite genre with another and keep the range equally narrow.","Change the meeting time before considering whether the reading choices need broadening."]},"advanced-native-1509-v1-final":{"type":"open","answers":["Our photography is no longer stuck in one lane. We still enjoy landscapes, but now we also try portraits and street scenes.","We do not want to stay stuck in one lane, so we are adding portraits to our usual landscape work."],"options":[]}}'::jsonb),
('advanced-native-1510', '["phrase"]'::jsonb, '{"advanced-native-1510-v1-audio":{"type":"mc","answers":["她樂於嘗試，仍可以有不喜歡的菜。"],"options":["她必須喜歡每道菜，才算願意嘗試。","句子重點是她比別人吃得更多。","她樂於嘗試，仍可以有不喜歡的菜。","她只願吃完全熟悉的菜式。"]},"advanced-native-1510-v2-reply":{"type":"mc","answers":["She is curious about dishes she has not tried before.","She can help us choose something beyond our usual meals.","She asks about ingredients and enjoys discovering different tastes.","She has an open palate and enjoys exploring unfamiliar flavours."],"options":["She is curious about dishes she has not tried before.","She can help us choose something beyond our usual meals.","She asks about ingredients and enjoys discovering different tastes.","She has an open palate and enjoys exploring unfamiliar flavours."]},"advanced-native-1510-v1-scene":{"type":"mc","answers":["She has an open palate."],"options":["She has an open palate.","She chooses familiar flavours and declines unfamiliar ones without asking about them.","She treats liking every dish as a condition of trying new food."]},"advanced-native-1510-v1-contrast":{"type":"mc","answers":["即使有飲食限制，也必須吃所有食物來證明開放。"],"options":["願意了解及嘗試不同味道。","即使有飲食限制，也必須吃所有食物來證明開放。","嘗試後仍可以有個人喜惡。"]},"advanced-native-1510-v1-branch":{"type":"mc","answers":["An open palate means being willing to explore, not having to like every dish."],"options":["Choose the safest familiar dish at each tasting so she will not need to express a dislike.","An open palate means being willing to explore, not having to like every dish.","Judge willingness only by the number of dishes the person finishes."]},"advanced-native-1510-v1-final":{"type":"open","answers":["An open palate can help guests explore new dishes at our food fair. They can still choose food that suits their needs.","We welcome an open palate at the food fair, without asking guests to enjoy every dish or ignore their own preferences."],"options":[]}}'::jsonb),
('advanced-native-1511', '["phrase"]'::jsonb, '{"advanced-native-1511-v1-audio":{"type":"mc","answers":["原有疑慮的食客逐漸產生好感。"],"options":["句子主要說廚師在烹飪比賽擊敗其他選手。","原有疑慮的食客逐漸產生好感。","廚師只是吸引目光，食客態度未有改善。","食客被要求表面同意，仍不支持廚師。"]},"advanced-native-1511-v2-reply":{"type":"mc","answers":["She wins people over with carefully prepared dishes and friendly explanations.","She listens to questions and explains the unfamiliar ingredients.","The dishes show care, and customers feel welcome.","People appreciate the attention she gives to their feedback."],"options":["She wins people over with carefully prepared dishes and friendly explanations.","She listens to questions and explains the unfamiliar ingredients.","The dishes show care, and customers feel welcome.","People appreciate the attention she gives to their feedback."]},"advanced-native-1511-v1-scene":{"type":"mc","answers":["She won them over by responding to their concerns."],"options":["She drew attention to the plan, but their support did not change.","She secured agreement mainly by pressuring them to stay quiet.","She won them over by responding to their concerns."]},"advanced-native-1511-v1-contrast":{"type":"mc","answers":["人們因怕被責怪而沉默，但私下仍反對。"],"options":["人們因怕被責怪而沉默，但私下仍反對。","可靠表現令顧客逐漸信任新服務。","耐心解釋後，原有疑慮者開始支持。"]},"advanced-native-1511-v1-branch":{"type":"mc","answers":["To win people over, we need genuine support rather than silence caused by pressure."],"options":["To win people over, we need genuine support rather than silence caused by pressure.","Use the lack of public complaints as the main sign that doubts have been resolved.","Stop asking for feedback once people no longer object in the meeting."]},"advanced-native-1511-v1-final":{"type":"open","answers":["The new puzzle game won people over with clear instructions and an engaging trial round. Shoppers who were doubtful began asking to play again.","The customers were unsure about the puzzle game, but a short demonstration won them over by making the rules easy to follow."],"options":[]}}'::jsonb),
('advanced-native-1512', '["phrase"]'::jsonb, '{"advanced-native-1512-v1-audio":{"type":"mc","answers":["幾種味道組合起來，帶來鮮明感受。"],"options":["幾種味道組合起來，帶來鮮明感受。","醬汁味道很淡，很難察覺各種風味。","醬汁只用辣味，沒有酸甜部分。","句子說每位食客都一定喜歡這個醬汁。"]},"advanced-native-1512-v2-reply":{"type":"mc","answers":["I want the sauce to add contrast without dominating the meal.","It has a punchy mix of sharp and sweet flavours.","The flavours are strong enough to notice in a small amount.","Too much could cover the gentler flavours in the dish."],"options":["I want the sauce to add contrast without dominating the meal.","It has a punchy mix of sharp and sweet flavours.","The flavours are strong enough to notice in a small amount.","Too much could cover the gentler flavours in the dish."]},"advanced-native-1512-v1-scene":{"type":"mc","answers":["The sauce has a punchy mix of flavours."],"options":["The sauce is so mild that its flavours are difficult to notice.","The sauce relies on a single taste without any contrast.","The sauce has a punchy mix of flavours."]},"advanced-native-1512-v1-contrast":{"type":"mc","answers":["punchy 必須只指辣椒的辣度，不包括酸或其他強烈味道。"],"options":["punchy 必須只指辣椒的辣度，不包括酸或其他強烈味道。","少量已可帶來明顯味道對比。","味道組合鮮明突出。"]},"advanced-native-1512-v1-branch":{"type":"mc","answers":["A punchy mix can use several strong flavours; think about their contrast as well as the heat."],"options":["Remove the lime and sweetness before deciding whether the combination has enough contrast.","A punchy mix can use several strong flavours; think about their contrast as well as the heat.","Increase the chilli first and use the amount of heat as the only description of the mix."]},"advanced-native-1512-v1-final":{"type":"open","answers":["The snack has a punchy mix of lime, herbs and spices, rather than a mild flavour. The menu should make that contrast clear.","We should describe the punchy mix of herbs and spices so guests know to expect a strong flavour."],"options":[]}}'::jsonb),
('advanced-native-1513', '["phrase"]'::jsonb, '{"advanced-native-1513-v1-audio":{"type":"mc","answers":["詢問食譜通常顯示喜歡，但語氣保留可能性。"],"options":["句子已嚴格證明每位客人都喜歡每道菜。","客人問食譜主要被解讀為拒絕那道菜。","句子沒有交代甚麼行為支持食客的反應。","詢問食譜通常顯示喜歡，但語氣保留可能性。"]},"advanced-native-1513-v2-reply":{"type":"mc","answers":["People asked how we made the broth.","The positive comments focused on its flavour.","They asked for the recipe; that usually says it all.","Several guests came back for another bowl."],"options":["People asked how we made the broth.","The positive comments focused on its flavour.","They asked for the recipe; that usually says it all.","Several guests came back for another bowl."]},"advanced-native-1513-v1-scene":{"type":"mc","answers":["They asked for the recipe; that usually says it all."],"options":["Their questions tell us only when dinner ended, not how they reacted.","They asked for the recipe; that usually says it all.","Their questions prove that every guest liked every course equally."]},"advanced-native-1513-v1-contrast":{"type":"mc","answers":["沒有交代 that 指甚麼，便單獨用 that usually says it all 作完整解釋。"],"options":["沒有交代 that 指甚麼，便單獨用 that usually says it all 作完整解釋。","說這是通常有意義的線索，同時保留其他可能原因。","先說客人主動問做法，再指出這通常已很能說明喜愛。"]},"advanced-native-1513-v1-branch":{"type":"mc","answers":["A long queue can be revealing; that usually says it all about demand, but not every aspect of quality."],"options":["A long queue can be revealing; that usually says it all about demand, but not every aspect of quality.","Use the queue as the full evaluation and skip checking service or food.","Treat the queue only as a record of opening hours rather than considering what it suggests about demand."]},"advanced-native-1513-v1-final":{"type":"open","answers":["Several students asked when the next performance would be; that usually says it all about their interest.","They wanted tickets for another show, and that usually says it all. It suggests that they enjoyed the performance."],"options":[]}}'::jsonb),
('advanced-native-1514', '["phrase"]'::jsonb, '{"advanced-native-1514-v1-audio":{"type":"mc","answers":["我們因喜歡招待及食物而再回去。"],"options":["我們只去過一次，之後沒有再光顧。","我們回去主要是投訴先前的服務。","我們因喜歡招待及食物而再回去。","我們只是回去拿遺下的物品，沒有再享用。"]},"advanced-native-1514-v2-reply":{"type":"mc","answers":["We enjoyed the food each time and wanted another visit.","The friendly service made it a comfortable place to return to.","There were more dishes we were curious to try.","The fresh bread kept us going back for more."],"options":["We enjoyed the food each time and wanted another visit.","The friendly service made it a comfortable place to return to.","There were more dishes we were curious to try.","The fresh bread kept us going back for more."]},"advanced-native-1514-v1-scene":{"type":"mc","answers":["The bread kept me going back for more."],"options":["I returned only to collect the bag I had left behind.","I enjoyed the bread but made no further visits.","The bread kept me going back for more."]},"advanced-native-1514-v1-contrast":{"type":"mc","answers":["回店只為拿遺失外套，沒有打算再享用。"],"options":["回店只為拿遺失外套，沒有打算再享用。","喜歡展覽，隔天再來看尚未細看的作品。","喜歡食物，想再吃一次。"]},"advanced-native-1514-v1-branch":{"type":"mc","answers":["Going back for more suggests wanting another enjoyable experience, not simply returning for a lost item."],"options":["Count visits without considering whether the person wanted more of the food or experience.","Going back for more suggests wanting another enjoyable experience, not simply returning for a lost item.","Describe a complaint-only visit as another enjoyable serving before asking why the customer returned."]},"advanced-native-1514-v1-final":{"type":"open","answers":["The hands-on experiments kept us going back for more. Each visit gave us another interesting challenge to try.","We were going back for more because the interactive exhibition made learning enjoyable."],"options":[]}}'::jsonb),
('advanced-native-1515', '["phrase"]'::jsonb, '{"advanced-native-1515-v1-audio":{"type":"mc","answers":["兩道菜在熟客偏好中有穩固地位。"],"options":["句子說每位顧客都把它們列作唯一首選。","兩道菜在熟客偏好中有穩固地位。","兩道菜因口感很硬才得到這個稱呼。","兩道菜剛推出，尚未知道顧客是否會再點。"]},"advanced-native-1515-v2-reply":{"type":"mc","answers":["They are firm favourites with our regular customers.","People have returned for them for years.","Customers often ask whether they are still available.","The dishes still hold a strong place among the familiar options."],"options":["They are firm favourites with our regular customers.","People have returned for them for years.","Customers often ask whether they are still available.","The dishes still hold a strong place among the familiar options."]},"advanced-native-1515-v1-scene":{"type":"mc","answers":["They remain firm favourites."],"options":["They remain firm favourites.","They are untested additions whose popularity is not yet known.","Their appeal has faded and regular customers now avoid ordering them."]},"advanced-native-1515-v1-contrast":{"type":"mc","answers":["一道新菜只推出一天，有人試過，尚未知道會否再點。"],"options":["一道新菜只推出一天，有人試過，尚未知道會否再點。","餐牌更新後，熟客仍經常詢問並點舊菜。","顧客多年來重複點選某些菜式。"]},"advanced-native-1515-v1-branch":{"type":"mc","answers":["Firm favourites suggests established appeal; we need more than a single day of curiosity."],"options":["Firm favourites suggests established appeal; we need more than a single day of curiosity.","Use the number of first-day samples as a substitute for repeat demand.","Describe the dish as an established favourite now and check later whether diners return for it."]},"advanced-native-1515-v1-final":{"type":"open","answers":["These two stories remain firm favourites with our reading group. Members still ask to read them again after several years.","The stories are firm favourites rather than a passing curiosity. New books have joined the list, but members still return to them."],"options":[]}}'::jsonb),
('advanced-native-1516', '["phrase"]'::jsonb, '{"advanced-native-1516-v1-audio":{"type":"mc","answers":["國際菜式仍有可辨認本地口味影響。"],"options":["國際菜式仍有可辨認本地口味影響。","餐牌只有本地菜，沒有外國菜式來源。","本地元素只在服務員說話口音，未影響食物。","菜式完全照外國食譜做，沒有本地調整。"]},"advanced-native-1516-v2-reply":{"type":"mc","answers":["Familiar touches remain even when the original recipes come from abroad.","The café has an international menu with a local accent.","The cook adapts some seasonings to flavours people know here.","The dishes combine overseas ideas with local ingredients."],"options":["Familiar touches remain even when the original recipes come from abroad.","The café has an international menu with a local accent.","The cook adapts some seasonings to flavours people know here.","The dishes combine overseas ideas with local ingredients."]},"advanced-native-1516-v1-scene":{"type":"mc","answers":["It offers an international menu with a local accent."],"options":["It offers an international menu with a local accent.","Its dishes follow overseas recipes without any local adaptation.","Its dishes all come from one local tradition rather than several international sources."]},"advanced-native-1516-v1-contrast":{"type":"mc","answers":["餐牌只翻譯成本地語言，菜式味道與做法未見本地影響。"],"options":["餐牌只翻譯成本地語言，菜式味道與做法未見本地影響。","幾種國際菜式加入本地食材與熟悉配搭。","外地菜式使用本地熟悉調味。"]},"advanced-native-1516-v1-branch":{"type":"mc","answers":["An international menu with a local accent should show local influence in the food, not only in its labels."],"options":["Remove the international dishes so the menu will show a stronger local accent.","An international menu with a local accent should show local influence in the food, not only in its labels.","Translate the names first and treat the language alone as evidence of adapted flavours."]},"advanced-native-1516-v1-final":{"type":"open","answers":["For the exchange dinner, we could create an international menu with a local accent by pairing overseas dishes with familiar local sauces.","An international menu with a local