('advanced-native-1526', '["phrase"]'::jsonb, '{"advanced-native-1526-v1-audio":{"type":"mc","answers":["家人仍是可尋求支持的穩定來源。"],"options":["她要獲得家人支持，就必須放棄獨立生活。","家人仍是可尋求支持的穩定來源。","她上大學後已不再向家人尋求任何支持。","句子只說大學宿舍的郵寄地址，沒有談支持。"]},"advanced-native-1526-v2-reply":{"type":"mc","answers":["They are still my home base when I need support.","Talking to them helps me think through the week.","I know they will listen before offering advice.","Their familiar support helps me face the next step."],"options":["They are still my home base when I need support.","Talking to them helps me think through the week.","I know they will listen before offering advice.","Their familiar support helps me face the next step."]},"advanced-native-1526-v1-scene":{"type":"mc","answers":["My family remains my home base."],"options":["My family remains my home base.","Moving away means I can no longer rely on any family support.","My family supports me only if I give up living independently."]},"advanced-native-1526-v1-contrast":{"type":"mc","answers":["有歸處就不能獨立探索其他地方。"],"options":["有歸處就不能獨立探索其他地方。","即使住得遠，家人也可以是支持來源。","有人或地方能提供穩定支持。"]},"advanced-native-1526-v1-branch":{"type":"mc","answers":["A home base can offer support while leaving room for independent decisions."],"options":["Wait until the person moves back before offering advice about life away.","A home base can offer support while leaving room for independent decisions.","Make practical support depend on following the family’s preferred choice."]},"advanced-native-1526-v1-final":{"type":"open","answers":["The community centre is our home base while we perform at different schools. We return there to plan rehearsals and ask our mentor for help.","Having a home base at the centre helps our travelling theatre group prepare for new performances."],"options":[]}}'::jsonb),
('advanced-native-1527', '["phrase"]'::jsonb, '{"advanced-native-1527-v1-audio":{"type":"mc","answers":["書目選擇範圍更廣，但比較可能較費時。"],"options":["書店選擇較多，因此每本書的質素已獲保證。","新書店只有舊攤檔原有的同樣幾種書。","書目選擇範圍更廣，但比較可能較費時。","新書店離得遠，所以 far 主要說路程。"]},"advanced-native-1527-v2-reply":{"type":"mc","answers":["I can compare several books on the same topic.","The wider selection includes different levels of difficulty.","I have a better chance of finding something suited to my course.","It offers far more choice in the subjects I need."],"options":["I can compare several books on the same topic.","The wider selection includes different levels of difficulty.","I have a better chance of finding something suited to my course.","It offers far more choice in the subjects I need."]},"advanced-native-1527-v1-scene":{"type":"mc","answers":["The new catalogue offers far more choice."],"options":["The new catalogue only changes delivery distance.","The wider range removes the need to compare suitability.","The new catalogue offers far more choice."]},"advanced-native-1527-v1-contrast":{"type":"mc","answers":["所有新增選項必定更便宜、更適合每個人。"],"options":["所有新增選項必定更便宜、更適合每個人。","選擇更多，可能需要更多比較時間。","可比較的選項範圍明顯增加。"]},"advanced-native-1527-v1-branch":{"type":"mc","answers":["Far more choice gives us a wider range, but we still need to compare what meets our needs."],"options":["Far more choice gives us a wider range, but we still need to compare what meets our needs.","Use the total number of options as the main measure of how suitable each one is.","Choose from the added options before checking their level because the range is larger."]},"advanced-native-1527-v1-final":{"type":"open","answers":["The new activity programme offers far more choice than the old one. Students can compare workshops that suit their interests and schedules.","We have far more choice after school, but we still need to check which workshops we can attend."],"options":[]}}'::jsonb),
('advanced-native-1528', '["phrase"]'::jsonb, '{"advanced-native-1528-v1-audio":{"type":"mc","answers":["小組用不理想但仍可用的資源應付。"],"options":["小組選到原本最想要的大房間。","小組完全沒有可用空間，因此取消活動。","小組只是比較房價，尚未使用任何房間。","小組用不理想但仍可用的資源應付。"]},"advanced-native-1528-v2-reply":{"type":"mc","answers":["We can adapt the activity to the room that is available.","It is not ideal, but there is still enough space for a short discussion.","We will make do with the smaller space and rearrange the chairs.","A tighter seating plan should let everyone join."],"options":["We can adapt the activity to the room that is available.","It is not ideal, but there is still enough space for a short discussion.","We will make do with the smaller space and rearrange the chairs.","A tighter seating plan should let everyone join."]},"advanced-native-1528-v1-scene":{"type":"mc","answers":["We made do with printed handouts."],"options":["We used our first-choice projector as planned.","We had no usable material and stopped the discussion.","We made do with printed handouts."]},"advanced-native-1528-v1-contrast":{"type":"mc","answers":["在資源充足下選到原本最想要的工具，毋須將就。"],"options":["房間較小，但調整安排繼續完成活動。","理想器材不能用，改用現有替代品。","在資源充足下選到原本最想要的工具，毋須將就。"]},"advanced-native-1528-v1-branch":{"type":"mc","answers":["We may be able to make do with the equipment we have if we adjust the activity."],"options":["Cancel before checking whether the available equipment can meet the essential needs.","Describe the substitute as the original first choice so the limitation will not need discussing.","We may be able to make do with the equipment we have if we adjust the activity."]},"advanced-native-1528-v1-final":{"type":"open","answers":["We can make do with plain fabric for the costumes. A simpler design will let us use the material we already have.","The theatre group had to make do with old cloth, but careful adjustments helped the costumes work on stage."],"options":[]}}'::jsonb),
