('advanced-native-1530', '["phrase"]'::jsonb, '{"advanced-native-1530-v1-audio":{"type":"mc","answers":["速度壓縮檢查，損害維修品質。"],"options":["速度壓縮檢查，損害維修品質。","服務只是更快，品質與檢查都未受影響。","故障漏查是因沒有顧客來，與趕工無關。","句子認為只要把所有步驟放慢，就不需任何檢查。"]},"advanced-native-1530-v2-reply":{"type":"mc","answers":["We need to protect reliability as well as speed.","The service was becoming too fast for its own good.","Rushed checks allowed faults to be missed.","A slightly longer check could reduce repeat repairs."],"options":["We need to protect reliability as well as speed.","The service was becoming too fast for its own good.","Rushed checks allowed faults to be missed.","A slightly longer check could reduce repeat repairs."]},"advanced-native-1530-v1-scene":{"type":"mc","answers":["The service has become too fast for its own good."],"options":["The main issue is delayed delivery rather than faults missed through rushed work.","The service has become too fast for its own good.","The faster service has maintained all the checks and the same reliability."]},"advanced-native-1530-v1-contrast":{"type":"mc","answers":["流程加快，但檢查完整，品質維持穩定。"],"options":["趕工令問題未被發現，之後反覆返修。","省略必要檢查，導致錯誤增加。","流程加快，但檢查完整，品質維持穩定。"]},"advanced-native-1530-v1-branch":{"type":"mc","answers":["Too fast for its own good means speed is causing harm; faster work can still be reliable when checks are protected."],"options":["Slow every step equally without finding where rushing caused the faults.","Too fast for its own good means speed is causing harm; faster work can still be reliable when checks are protected.","Judge quality by waiting time alone before looking at errors or checks."]},"advanced-native-1530-v1-final":{"type":"open","answers":["Our publishing process became too fast for its own good. We should keep a short check to catch mistakes in the times.","The process is too fast for its own good when rushing leads to repeated errors. A final check could help."],"options":[]}}'::jsonb),
('advanced-native-1531', '["phrase"]'::jsonb, '{"advanced-native-1531-v1-audio":{"type":"mc","answers":["活動較方便安排，卻減少部分個人溫暖。"],"options":["組織者因失敗而完全失去勇氣。","活動增加了個人故事，感覺比以前更親近。","所有活動內容都已失去價值，沒有任何好處。","活動較方便安排，卻減少部分個人溫暖。"]},"advanced-native-1531-v2-reply":{"type":"mc","answers":["The programme ran smoothly, but people had fewer chances to connect.","The practical improvement came with a loss of some personal warmth.","It lost a bit of heart when we stopped sharing our own stories.","The standard recording left less room for individual memories."],"options":["The programme ran smoothly, but people had fewer chances to connect.","The practical improvement came with a loss of some personal warmth.","It lost a bit of heart when we stopped sharing our own stories.","The standard recording left less room for individual memories."]},"advanced-native-1531-v1-scene":{"type":"mc","answers":["The evening lost a bit of heart."],"options":["The new format gave people more chances to share personal memories.","The evening lost a bit of heart.","The organisers lost the courage to hold any event."]},"advanced-native-1531-v1-contrast":{"type":"mc","answers":["主語是晚會，卻直接解作某位組織者灰心。"],"options":["形式仍有用，但少了部分個人溫暖。","主語是晚會，卻直接解作某位組織者灰心。","實際便利與人情味可以有不同變化。"]},"advanced-native-1531-v1-branch":{"type":"mc","answers":["It lost a bit of heart, so let us restore personal sharing while keeping the useful arrangements."],"options":["It lost a bit of heart, so let us restore personal sharing while keeping the useful arrangements.","Remove every practical improvement before checking which change reduced personal contact.","Keep only the smooth timetable and leave out how participants felt about the evening."]},"advanced-native-1531-v1-final":{"type":"open","answers":["The shop became quicker to use, but it lost a bit of heart when regular customers stopped chatting with staff.","The service lost a bit of heart after the move to self-service. Keeping someone available to help could restore some warmth