('advanced-native-1535', '["phrase"]'::jsonb, '{"advanced-native-1535-v1-audio":{"type":"mc","answers":["短暫到不同環境調劑，之後仍繼續工作。"],"options":["小組已永久離開項目，不再回去。","他們只改任務次序，仍一直留在室內工作。","小組打算等長假再離開室內，而非先短暫散步。","短暫到不同環境調劑，之後仍繼續工作。"]},"advanced-native-1535-v2-reply":{"type":"mc","answers":["I wanted a brief break from the same surroundings.","Seeing a different place gave me a fresh pause in the day.","I needed a change of scene after being indoors all morning.","A few minutes outside helped me feel ready to return."],"options":["I wanted a brief break from the same surroundings.","Seeing a different place gave me a fresh pause in the day.","I needed a change of scene after being indoors all morning.","A few minutes outside helped me feel ready to return."]},"advanced-native-1535-v1-scene":{"type":"mc","answers":["The park offered a change of scene."],"options":["I postponed any break until I could take a long holiday.","I switched to another chapter at the same desk without leaving the room.","The park offered a change of scene."]},"advanced-native-1535-v1-contrast":{"type":"mc","answers":["一定要永久搬家，短暫離開不算。"],"options":["到不同環境可有調劑。","一定要永久搬家，短暫離開不算。","短散步後仍可回去做原工作。"]},"advanced-native-1535-v1-branch":{"type":"mc","answers":["A short walk could give us a change of scene before we return to the task."],"options":["A short walk could give us a change of scene before we return to the task.","Let us switch to another chapter at the same desk and call that a change in surroundings.","Put off any change of surroundings until we can take a whole week away."]},"advanced-native-1535-v1-final":{"type":"open","answers":["The local exhibition could offer a change of scene during the holiday. We can visit for an hour and return home for dinner.","Let us have a change of scene instead of spending another afternoon with the same programmes at home."],"options":[]}}'::jsonb),
('advanced-native-1536', '["phrase"]'::jsonb, '{"advanced-native-1536-v1-audio":{"type":"mc","answers":["她停下來看周遭平常生活。"],"options":["她正按購物清單趕着辦事，而不是停下觀察。","她感到被周遭活動排除，想立即離開。","她停下來看周遭平常生活。","她只在看預錄新聞，沒有留意窗外。"]},"advanced-native-1536-v2-reply":{"type":"mc","answers":["I notice the small routines of people passing outside.","It is a quiet chance to observe the neighbourhood.","I enjoy seeing people shop and meet their friends.","I like to watch the world go by for a while."],"options":["I notice the small routines of people passing outside.","It is a quiet chance to observe the neighbourhood.","I enjoy seeing people shop and meet their friends.","I like to watch the world go by for a while."]},"advanced-native-1536-v1-scene":{"type":"mc","answers":["I sat to watch the world go by."],"options":["I sat to watch the world go by.","I hurried across the square to finish my own shopping.","I watched an old television programme without looking at the square."]},"advanced-native-1536-v1-contrast":{"type":"mc","answers":["因為看了一會日常，就表示整天沒有做任何事。"],"options":["因為看了一會日常，就表示整天沒有做任何事。","可在等人或休息時短暫觀察。","悠閒觀察路人和日常活動。"]},"advanced-native-1536-v1-branch":{"type":"mc","answers":["People can watch the world go by simply because they enjoy a quiet pause."],"options":["Use a few minutes of observation as the main evidence that the person has no friends.","Assume the whole day was empty before asking what the person was doing earlier.","People can watch the world go by simply because they enjoy a quiet pause."]},"advanced-native-1536-v1-final":{"type":"open","answers":["Let us leave one holiday morning free to watch the world go by from the terrace. We do not need to fill every hour with sightseeing.","Instead of rushing from landmark to landmark, we could sit on the terrace and watch the world go by over breakfast."],"options":[]}}'::jsonb),
