('advanced-native-1550', '["phrase"]'::jsonb, '{"advanced-native-1550-v1-audio":{"type":"mc","answers":["她等候時感到緊張，結果仍未知。"],"options":["她很放鬆，完全沒有緊張感。","句子說她站在一條真實邊界上，沒有談感受。","她等候時感到緊張，結果仍未知。","她已收到失敗通知，所以結果確定。"]},"advanced-native-1550-v2-reply":{"type":"mc","answers":["She found it hard to relax during the wait.","She was nervous because she did not know how it would go.","The uncertainty made her feel tense.","She felt on edge despite having prepared."],"options":["She found it hard to relax during the wait.","She was nervous because she did not know how it would go.","The uncertainty made her feel tense.","She felt on edge despite having prepared."]},"advanced-native-1550-v1-scene":{"type":"mc","answers":["I feel on edge before the performance."],"options":["I feel on edge before the performance.","The performance has already failed, so there is no uncertainty.","I am describing only where I stand, not how I feel."]},"advanced-native-1550-v1-contrast":{"type":"mc","answers":["不安已證明不好的結果一定會發生。"],"options":["不安已證明不好的結果一定會發生。","需要更多情境才能知道緊張原因。","對方感到緊張不安。"]},"advanced-native-1550-v1-branch":{"type":"mc","answers":["Feeling on edge tells us you are tense, not that the performance must go badly."],"options":["Feeling on edge tells us you are tense, not that the performance must go badly.","Treat the feeling as the final result before the performance starts.","Use one nervous moment as enough evidence to cancel without discussing what support would help."]},"advanced-native-1550-v1-final":{"type":"open","answers":["I feel on edge while waiting for the important parcel, but I do not know yet whether it will arrive today. I will check the tracking update.","The uncertain delivery time leaves me on edge; the feeling does not tell me what has happened to the parcel."],"options":[]}}'::jsonb),
('advanced-native-1552', '["phrase"]'::jsonb, '{"advanced-native-1552-v1-audio":{"type":"mc","answers":["熱湯正配合 Maya 當時想要的感受。"],"options":["熱湯正配合 Maya 當時想要的感受。","句子客觀證明每人都必須喝同一種湯。","Maya 原先想要另一類口感，這碗湯沒有符合她的需要。","Maya 選它主要是因為多人推薦，句子沒有表達她自己的滿足。"]},"advanced-native-1552-v2-reply":{"type":"mc","answers":["It suited what I felt like having at that moment.","It really hit the spot.","It was exactly the simple warmth I wanted.","I found it comforting after being out in the cold."],"options":["It suited what I felt like having at that moment.","It really hit the spot.","It was exactly the simple warmth I wanted.","I found it comforting after being out in the cold."]},"advanced-native-1552-v1-scene":{"type":"mc","answers":["The warm porridge hit the spot."],"options":["My reaction establishes what everyone else must want too.","The warm porridge hit the spot.","The porridge missed the kind of comfort I wanted."]},"advanced-native-1552-v1-contrast":{"type":"mc","answers":["所有人在任何時間都必定有相同滿足。"],"options":["同一食物在不同情境未必一樣合意。","某事物正合當下心意。","所有人在任何時間都必定有相同滿足。"]},"advanced-native-1552-v1-branch":{"type":"mc","answers":["It may hit the spot for you, while someone else wants something different."],"options":["It may hit the spot for you, while someone else wants something different.","Use your satisfaction as the main reason to choose everyone else’s drink before asking them.","Keep the same choice for every occasion without considering what people feel like having."]},"advanced-native-1552-v1-final":{"type":"open","answers":["The quiet acoustic guitar set really hit the spot after a busy week. It was the relaxed evening I wanted.","For me, the gentle music hit the spot, though someone looking for a lively party might prefer something else."],"options":[]}}'::jsonb),
('advanced-native-1553', '["phrase"]'::jsonb, '{"advanced-native-1553-v1-audio":{"type":"mc","answers":["她比較哪種安排較配合自己的身體需要。"],"options":["她把朋友的安排當成已證明適合所有人的方案。","better 表示她已找出對所有年齡最健康的唯一安排。","她只比較哪種安排看起來較時髦，不考慮個人身體需要。","她比較哪種安排較配合自己的身體需要。"]},"advanced-native-1553-v2-reply":{"type":"mc","answers":["She is paying attention to her individual needs.","A comparison can help her make a more suitable personal choice.","She wants to consider what suits her body better.","Her own comfort may differ from her friend’s."],"options":["She is paying attention to her individual needs.","A comparison can help her make a more suitable personal choice.","She wants to consider what suits her body better.","Her own comfort may differ from her friend’s."]},"advanced-native-1553-v1-scene":{"type":"mc","answers":["Maya is considering what suits her body better."],"options":["Maya is considering what suits her body better.","Maya has established one routine as the healthiest choice for everyone.","Maya is copying another person’s preference without considering her own needs."]},"advanced-native-1553-v1-contrast":{"type":"mc","answers":["哪個已被證實對所有人最健康。"],"options":["在可選方案中，比較她的舒適感與需要。","哪個較配合她的個人身體需要。","哪個已被證實對所有人最健康。"]},"advanced-native-1553-v1-branch":{"type":"mc","answers":["What suits her body better concerns Maya’s comparison, not a rule for everyone."],"options":["Replace better with best and leave the individual context out.","Use Maya’s preference as enough evidence for other people’s needs before asking about them.","What suits her body better concerns Maya’s comparison, not a rule for everyone."]},"advanced-native-1553-v1-final":{"type":"open","answers":["Maya is considering what suits her body better when choosing a rehearsal time. Other musicians may have different needs.","Maya wants to notice what suits her body better rather than assume the earlier session must suit everyone."],"options":[]}}'::jsonb),
('advanced-native-1554', '["phrase"]'::jsonb, '{"advanced-native-1554-v1-audio":{"type":"mc","answers":["她用車輛燃料比喻早上活動所需能量。"],"options":["她把早餐當作完成所有上午工作之後才做的安排。","她只在規劃工作時間，沒有表達自己可用的能量。","她用車輛燃料比喻早上活動所需能量。","她覺得能量完全充足，所以取消原定稍後休息。"]},"advanced-native-1554-v2-reply":{"type":"mc","answers":["The image expresses having some energy available.","She is comparing her morning effort with a vehicle needing fuel.","It is her way of describing preparation for the morning.","She thinks of it as fuel in the tank to help her get started."],"options":["The image expresses having some energy available.","She is comparing her morning effort with a vehicle needing fuel.","It is her way of describing preparation for the morning.","She thinks of it as fuel in the tank to help her get started."]},"advanced-native-1554-v1-scene":{"type":"mc","answers":["I have some fuel in the tank for the next stage."],"options":["I do not have enough energy to begin even the first box.","I have some fuel in the tank for the next stage.","I plan to do every remaining task tonight without checking how I feel."]},"advanced-native-1554-v1-contrast":{"type":"mc","answers":["有了能量就保證不再疲倦，也不用休息。"],"options":["有了能量就保證不再疲倦，也不用休息。","仍可需要計劃步驟及休息。","有一些可支援下一步的能量。"]},"advanced-native-1554-v1-branch":{"type":"mc","answers":["Fuel in the tank suggests energy to continue, not a guarantee that every task will be finished without rest."],"options":["Remove the planned break from the account so the metaphor sounds stronger.","Fuel in the tank suggests energy to continue, not a guarantee that every task will be finished without rest.","Schedule the entire job for tonight without considering how long the character’s energy may last."]},"advanced-native-1554-v1-final":{"type":"open","answers":["I still have some fuel in the tank, coach. I can help defend for the last few minutes; which position should I cover?","With a little fuel in the tank, I could cover a defensive position for a short spell. Please tell me where you need