('advanced-native-1555', '["phrase"]'::jsonb, '{"advanced-native-1555-v1-audio":{"type":"mc","answers":["歌曲短暫提振心情，沒有代替完成工作。"],"options":["句子主要表示她已完成所有餘下工作。","歌曲短暫提振心情，沒有代替完成工作。","Maya 覺得歌曲令人更疲倦，心情也更低落。","Maya 正要求有人到車站接她。"]},"advanced-native-1555-v2-reply":{"type":"mc","answers":["It was a small pick-me-up.","It gave her mood a brief lift.","It made the pause feel more refreshing.","She felt a little brighter after listening."],"options":["It was a small pick-me-up.","It gave her mood a brief lift.","It made the pause feel more refreshing.","She felt a little brighter after listening."]},"advanced-native-1555-v1-scene":{"type":"mc","answers":["The encouraging feedback was a welcome pick-me-up."],"options":["The encouraging feedback was a welcome pick-me-up.","The feedback left me more discouraged about rehearsing.","The teacher was arranging a lift home rather than commenting on my progress."]},"advanced-native-1555-v1-contrast":{"type":"mc","answers":["對司機說 Please pick me up at the station，請他到車站接人。"],"options":["對司機說 Please pick me up at the station，請他到車站接人。","人物說簡短休息是令自己心情好一點的小調劑。","一首喜歡的歌帶來短暫精神提振。"]},"advanced-native-1555-v1-branch":{"type":"mc","answers":["It was a welcome pick-me-up. I felt a bit brighter, and I would still like to discuss tomorrow’s workload."],"options":["It was a welcome pick-me-up. I felt a bit brighter, and I would still like to discuss tomorrow’s workload.","I meant that you had offered me a ride home after the shift, not that the note cheered me up.","I felt more discouraged by the note, so I would rather avoid discussing tomorrow’s workload."]},"advanced-native-1555-v1-final":{"type":"open","answers":["The friendly message was a welcome pick-me-up during my first week at a new school. I still need time to settle in.","A short note from an old classmate gave me a pick-me-up, even though the new routine still felt unfamiliar."],"options":[]}}'::jsonb)
